"""Assemble the scoped evidence from completed native checks; no game execution."""
from pathlib import Path
import difflib
import hashlib
import json
import re
import subprocess

ROOT = Path(__file__).resolve().parents[3]
E = Path(__file__).resolve().parent
PREFIX = E.relative_to(ROOT).as_posix()
BASE = "powershell -NoProfile -ExecutionPolicy Bypass -File scripts/dev.ps1"

def read_log(name):
    raw = (E / name).read_bytes()
    return raw.decode("utf-16" if raw.startswith(b"\xff\xfe") else "utf-8-sig")

tests = []
for name, script, renderer, timeout, action in [
    ("edges-headless", "test_desert_dune_edges", "", 240, "TestScript"),
    ("edges-mobile", "test_desert_dune_edges", "mobile", 300, "TestScript"),
    ("edges-compatibility", "test_desert_dune_edges", "gl_compatibility", 300, "TestScript"),
    ("wind-headless", "test_desert_sand_wind", "", 180, "TestScript"),
    ("wind-mobile", "test_desert_sand_wind", "mobile", 300, "TestScript"),
    ("wind-compatibility", "test_desert_sand_wind", "gl_compatibility", 300, "TestScript"),
    ("ambience-headless", "test_desert_ambience", "", 180, "TestScript"),
    ("desert-headless", "", "", 180, "TestDesert"),
    ("biomes-headless", "", "", 180, "TestBiomes"),
    ("parser", "test_script_parse", "", 240, "TestScript"),
]:
    log = name + ".log"
    matches = re.findall(r"([A-Z_]+): (\d+) (checks|scripts), (\d+) failures", read_log(log))
    assert matches, log
    result = matches[-1]
    assert result[3] == "0", (log, result)
    command = BASE + " -Action " + action
    if script: command += " -ScriptPath res://tests/" + script + ".gd"
    if renderer: command += " -Graphical -RenderingMethod " + renderer
    if name.startswith("wind-") and renderer: command += f" -TestArgument '--evidence=res://../{PREFIX}/focused'"
    command += " -CommandTimeoutSeconds " + str(timeout)
    tests.append(dict(log=log, checks=int(result[1]), failures=int(result[3]), command=command))

native = {}
for renderer in ("mobile", "gl_compatibility"):
    native[renderer] = json.loads((E / renderer / "race.json").read_text())
    native[renderer]["palette"] = json.loads((E / "focused" / renderer / "palette.json").read_text())
    name = "wind-mobile.log" if renderer == "mobile" else "wind-compatibility.log"
    roof = re.search(r"SAND_OPAQUE_SAMPLES: (\d+) changed=(\d+)", read_log(name))
    native[renderer]["opaque_roof"] = dict(samples=int(roof[1]), changed=int(roof[2]))

table = "\n".join(f"| {t['log']} | {t['checks']} | 0 |" for t in tests)
counts = "/".join(str(tests[i]["checks"]) for i in range(3))
wind_counts = "/".join(str(tests[i]["checks"]) for i in range(3, 6))
coverage = re.search(r"DUNE_EDGE_COVERAGE: (\d+)/80", read_log("edges-headless.log"))[1]
doc_path = "docs/DESERT_DUNE_EDGES_2026_10_24.md"
doc = f"""# Desert texture-edge wind — 2026-10-24

Requirements: DDE01 start blown sand at painted dune edges; DDE02 show bursts more frequently; DDE03 preserve ordinary-driving visibility and complete scenery; R01 canonical isolation; G01 native review; Q01 scoped checkpoint.

## Result and implementation

Sand births use 14 authored crest guides in the existing `desert_sand_v2.png`. Each guide supplies eight birth coordinates. The broad, high-contrast edges are traced within artist-selected windows; the softly lit lower crowns use pinned lip coordinates so the tracer cannot jump onto an unrelated ripple. The atlas is data generated by `scripts/bake_desert_dune_edges.py`; the PNG is unchanged, SHA256 `716bddbf85086fa1d226ac0b58a44d14418b85d656fe6dcfe9f3776696df95aa`.

Use the visible albedo's exact **world XZ / 28m** coordinates, including negative-world wrapping. The unrelated 32m normal-map tile does not position emitters. Every MultiMesh instance starts at its own traced root. Remove the original lateral birth jitter; cards start narrow and nearly touching the ground, widen after lift, then drift downwind. Even age spacing and a per-layer opacity cap keep coincident root cards from building hard cores. Airborne hue, low lift and depth/roof exclusion remain.

Ground support comes from the actual terrain floor and shared Desert relief. A conservative occupied-cell index excludes the raised banks whose shader replaces the photo with vertex pigment; a loose-surface margin avoids the road fringe. It scans the prepared geometry once and coalesces its projection rather than retaining all subdivision triangles. The native fixture reads 84,680 input triangles into 1,671 occupied cells. The cell map is capped at 65,536 entries and coarsens conservatively if needed. A local 3×3 tile window follows the car, so the anchor cap does not fill with one end of a large map. At most 126 new sites/1,008 root probes are considered per refresh, plus up to six retained live sites.

Entire sites fade by their source distance before releasing their slot. CPU retirement and the shader share the same 14–20m source fade. The visible-site stability test now references that shared constant (still 20m); its guarantee is preserved. No arbitrary flat-ground fallback remains: all emitted roots come from the artwork guides. Empty or covered guide locations stay empty.

Independent periods change **5–9s → 3.6–6s**, retaining the 10% skipped-event variation. This is about **46% more nominal starts** at a site, inferred from the mean periods, not a measured device-wide start count. Durations are 2.3–3.2s, bounded to fade before a cycle rolls over. Six sites still share 48 quads/96 triangles. Wind audio, camera, terrain artwork, pyramid repair and canonical driving code are outside the runtime edit scope.

## Actual verification

Godot 4.7.2.stable.official.ed1daf0bf; desktop NVIDIA RTX 3090. Exact commands, source hashes and native numbers are in [report.json](evidence/desert-dune-edges-2026-10-24/report.json).

| Retained log | Checks/scripts | Failures |
|---|---:|---:|
{table}

The edge fixture checks the artwork hash; every particle's repeated UV coordinates and real MultiMesh transform; loose-ground/bridge exclusions; retained-root stability; bounded moving discovery; and {coverage}/80 nearby-source road positions. The headless dummy has no MultiMesh buffer, so transform publication is checked on both native renderers. It then uses actual App cold/cached race installation, shared pyramid resources, complete ground, loading barriers, native pyramid pixels and ordinary seeded weather along a scripted 50km/h route. The canonical track bytes remain exact.

At >=1% channel contrast, sand is visible in {native['mobile']['visible_samples']}/18 Mobile samples (peak {native['mobile']['peak_pixels']} pixels) and {native['gl_compatibility']['visible_samples']}/18 Compatibility samples (peak {native['gl_compatibility']['peak_pixels']}). The stricter >=2% check passes {native['mobile']['clear_samples']}/18 and {native['gl_compatibility']['clear_samples']}/18 respectively. Both original visibility thresholds remain unchanged: nine samples with at least 1,000 pixels and a peak of at least 3,000. Hue, saturation, quiet intervals, soft-core contrast, bright-speck, lifecycle and opaque-roof checks also retain their limits. No failed invariant was weakened.

[Native preview](evidence/desert-dune-edges-2026-10-24/preview.html) includes the actual artwork/root overlay, a sand on/off comparison in the same driving frame, and native motion links. These are Godot captures, not generated or retouched images. Explicit readbacks/pixel loops cause capture hitch diagnostics; they are not game FPS measurements.

## Corrections, scope and remaining acceptance

Retained initial logs cover the generated packed-array constant parse correction, the headless dummy-buffer fixture correction, too-dense root cards, too-small source-support triangle budgets and weaker contrast trials. The final support index coalesces cells rather than rejecting a whole family. A concurrent `recording_cache.gd` parse edit interrupted the first final focused/biome runs; its correction was left to that concurrent work and the checks were rerun. The default Python lacks Pillow; the existing `.tools/review` environment is used without installing dependencies. No runtime image loading or extra bitmap asset is introduced.

Changed runtime files are the two sand files and the new `desert_dune_edges.gd`/`desert_dune_source_surface.gd`. The existing full-App fixture gains an optional capture-output path; its original deformer control stays pinned to its original evidence. The wind fixture uses the shared source-fade constant and logs prepared support. The new edge fixture extends the complete race regression. The bake script, this document, three status files and scoped evidence complete the change. `checkpoint.patch` is based on task-entry snapshots, with a reverse-application check against the working tree; concurrent changes are retained.

Artist recognition of every selected lip, sustained appearance on the owner's affected track, and physical-device preparation/fragment cost remain to be accepted. Coarsening can conservatively omit an edge on an unusually large world; it cannot authorize a birth on a covered bank. The support scan occurs during race preparation; no Android load-time/FPS claim is made. No phone/tablet attachment check or physical-device test was performed. No APK/export/install, native rebuild, live account/backend mutation or deployment occurred. Existing owner processes remain running. Local source changes require a client restart; installed phone/tablet builds have not been updated.
"""
(ROOT / doc_path).write_bytes(doc.encode())

status = f"2026-10-24 DDE01-DDE03/R01/G01/Q01: Wind births follow14 painted dune-edge guides at exact worldXZ/28m UVs, with pinned soft lip roots, narrow attached births, bounded projected bank exclusion and moving local discovery. Independent periods5-9s become3.6-6s (~46% more nominal starts); six sites/48quads/96triangles remain. Full-App edge/scenery {counts}, focused {wind_counts}, ambience111, Desert87, biomes108 and parser{tests[-1]['checks']} pass. Native1% samples {native['mobile']['visible_samples']}/18 Mobile/{native['gl_compatibility']['visible_samples']}/18 Compatibility; stricter2% {native['mobile']['clear_samples']}/18/{native['gl_compatibility']['clear_samples']}/18. All sampled roof pixels exact; hue/soft-core/lifecycle/canonical guards remain. Initial support/shape/fixture and concurrent-cache parse corrections retained. Native preview, commands, hashes and scoped checkpoint: {doc_path} and {PREFIX}/report.json. Restart and owner lip/track/device cost acceptance remain. No device check/test, APK, live mutation or deployment; concurrent work and owner processes preserved.\n\n"
status_paths = ["AGENTS.md", "DEVELOPMENT_STATUS.md", "docs/PHASE_0_PLAN.md"]
for relative in status_paths:
    path = ROOT / relative
    snapshot = E / "before" / relative.replace("/", "__")
    if not snapshot.exists(): snapshot.write_bytes(path.read_bytes())
    marker = "## Texture-edge Desert wind" if relative == "AGENTS.md" else "2026-10-24 DDE01"
    if not path.read_text(encoding="utf-8").startswith(marker):
        heading = "## Texture-edge Desert wind override (2026-10-24)\n" if relative == "AGENTS.md" else ""
        path.write_bytes((heading + status).encode() + path.read_bytes())

old_files = ["game/track/desert_sand_wind.gd", "game/track/desert_sand_wind.gdshader", "game/tests/test_desert_sand_wind.gd", "game/tests/test_desert_visibility_regression.gd"]
new_files = ["game/track/desert_dune_edges.gd", "game/track/desert_dune_source_surface.gd", "game/tests/test_desert_dune_edges.gd", "scripts/bake_desert_dune_edges.py", doc_path, PREFIX + "/preview.html", PREFIX + "/finish_receipt.py"]
new_files += [name + ".uid" for name in new_files[:3]]
paths = old_files + new_files + status_paths
patch, manifest = [], []
(E / "after").mkdir(exist_ok=True)
for relative in paths:
    path = ROOT / relative
    before = E / "before" / (relative.replace("/", "__") if relative in status_paths else path.name)
    old = before.read_text(encoding="utf-8") if relative in old_files + status_paths else ""
    new = path.read_text(encoding="utf-8")
    patch.append(f"diff --git a/{relative} b/{relative}\n")
    patch.extend(difflib.unified_diff(old.splitlines(True), new.splitlines(True), fromfile="a/"+relative if old else "/dev/null", tofile="b/"+relative))
    manifest.append(dict(path=relative, sha256=hashlib.sha256(path.read_bytes()).hexdigest(), before_sha256=hashlib.sha256(before.read_bytes()).hexdigest() if old else None))
    (E / "after" / relative.replace("/", "__")).write_bytes(path.read_bytes())
(E / "checkpoint.patch").write_bytes("".join(patch).encode())
git_checks = []
for command in (["git", "diff", "--check", "--"] + paths, ["git", "apply", "--reverse", "--check", str(E / "checkpoint.patch")]):
    result = subprocess.run(command, cwd=ROOT, capture_output=True, text=True)
    git_checks.append(dict(command=command, exit_code=result.returncode, output=result.stdout+result.stderr))
    assert result.returncode == 0, git_checks[-1]
report = dict(date="2026-10-24", requirements=["DDE01","DDE02","DDE03","R01","G01","Q01"], engine="4.7.2.stable.official.ed1daf0bf", gpu="desktop RTX 3090", tests=tests, native=native, atlas=json.loads((E / "atlas.json").read_text()), nominal_start_increase=7/4.8-1, changed_files=manifest, git_checks=git_checks, limits=["Owner lip/track appearance acceptance pending", "No physical-device appearance, load-time or fragment-cost measurement", "No device attachment check, APK, install or deployment", "Conservative occupancy coarsening can omit sites on unusually large worlds", "Concurrent work and owner processes preserved"])
report["bake_validation"] = {"commands": [".tools/review/Scripts/python.exe scripts/bake_desert_dune_edges.py", ".tools/review/Scripts/python.exe scripts/bake_desert_dune_edges.py --check", "python -m py_compile scripts/bake_desert_dune_edges.py docs/evidence/desert-dune-edges-2026-10-24/finish_receipt.py"], "exact_repeat": True, "log": "repeat-bake.log"}
(E / "report.json").write_bytes((json.dumps(report, indent=2)+"\n").encode())
print(json.dumps(dict(tests=len(tests), failures=0, git_checks=[item["exit_code"] for item in git_checks], report=str(E / "report.json"))))
